using UnityEngine;
using System.IO;
using System.Collections.Generic; // Required for List


[System.Serializable]
public class InitialEnvironmentData
{
    // These fields match the keys in the JSON generated by Python.
    // NumPy arrays are converted to nested lists.
    public List<List<float>> height_map;
    public List<List<int>> veg_map;
    public List<List<float>> fuel_map;
    public List<List<float>> fuel_moisture_map;
    public List<float> burn_box_coords;
    public List<bool[]> burn_box_mask;
    public GridMetadata grid_metadata;
}